// AsFolderNode returns the union data inside the TreeNode as a FolderNode
func (t TreeNode) AsFolderNode() (FolderNode, error) {
	var body FolderNode
	err := json.Unmarshal(t.union, &body)
	return body, err
}

// FromFolderNode overwrites any union data inside the TreeNode as the provided FolderNode
func (t *TreeNode) FromFolderNode(v FolderNode) error {
	v.Kind = "folder"
	b, err := json.Marshal(v)
	t.union = b
	return err
}

// MergeFolderNode performs a merge with any union data inside the TreeNode, using the provided FolderNode
func (t *TreeNode) MergeFolderNode(v FolderNode) error {
	v.Kind = "folder"
	b, err := json.Marshal(v)
	if err != nil {
		return err
	}

	merged, err := runtime.JSONMerge(t.union, b)
	t.union = merged
	return err
}

// AsNoteNode returns the union data inside the TreeNode as a NoteNode
func (t TreeNode) AsNoteNode() (NoteNode, error) {
	var body NoteNode
	err := json.Unmarshal(t.union, &body)
	return body, err
}

// FromNoteNode overwrites any union data inside the TreeNode as the provided NoteNode
func (t *TreeNode) FromNoteNode(v NoteNode) error {
	v.Kind = "note"
	b, err := json.Marshal(v)
	t.union = b
	return err
}

// MergeNoteNode performs a merge with any union data inside the TreeNode, using the provided NoteNode
func (t *TreeNode) MergeNoteNode(v NoteNode) error {
	v.Kind = "note"
	b, err := json.Marshal(v)
	if err != nil {
		return err
	}

	merged, err := runtime.JSONMerge(t.union, b)
	t.union = merged
	return err
}

// AsFileNode returns the union data inside the TreeNode as a FileNode
func (t TreeNode) AsFileNode() (FileNode, error) {
	var body FileNode
	err := json.Unmarshal(t.union, &body)
	return body, err
}

// FromFileNode overwrites any union data inside the TreeNode as the provided FileNode
func (t *TreeNode) FromFileNode(v FileNode) error {
	v.Kind = "file"
	b, err := json.Marshal(v)
	t.union = b
	return err
}

// MergeFileNode performs a merge with any union data inside the TreeNode, using the provided FileNode
func (t *TreeNode) MergeFileNode(v FileNode) error {
	v.Kind = "file"
	b, err := json.Marshal(v)
	if err != nil {
		return err
	}

	merged, err := runtime.JSONMerge(t.union, b)
	t.union = merged
	return err
}

func (t TreeNode) Discriminator() (string, error) {
	var discriminator struct {
		Discriminator string `json:"kind"`
	}
	err := json.Unmarshal(t.union, &discriminator)
	return discriminator.Discriminator, err
}

func (t TreeNode) ValueByDiscriminator() (interface{}, error) {
	discriminator, err := t.Discriminator()
	if err != nil {
		return nil, err
	}
	switch discriminator {
	case "file":
		return t.AsFileNode()
	case "folder":
		return t.AsFolderNode()
	case "note":
		return t.AsNoteNode()
	default:
		return nil, errors.New("unknown discriminator value: " + discriminator)
	}
}

func (t TreeNode) MarshalJSON() ([]byte, error) {
	b, err := t.union.MarshalJSON()
	return b, err
}

func (t *TreeNode) UnmarshalJSON(b []byte) error {
	err := t.union.UnmarshalJSON(b)
	return err
}

// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Trigger a full or incremental re-index
	// (POST /admin/reindex)
	PostAdminReindex(w http.ResponseWriter, r *http.Request)
	// Report the migration runner state
	// (GET /admin/status)
	GetAdminStatus(w http.ResponseWriter, r *http.Request)
	// Upload an attachment to a note's attachments/ directory (ATTACH-01..04).
	// (POST /attachments/{noteId})
	CreateAttachment(w http.ResponseWriter, r *http.Request, noteId string)
	// Stream an attachment file (ATTACH-05/06; path-traversal hardened).
	// (GET /attachments/{noteId}/{filename})
	GetAttachment(w http.ResponseWriter, r *http.Request, noteId string, filename string)
	// Create a new bookmark folder (virtual grouping label) (BOOK-03)
	// (POST /bookmark-folders)
	CreateBookmarkFolder(w http.ResponseWriter, r *http.Request)
	// Read the whole bookmarks document (folders + bookmarks, auto-pruned) (BOOK-01)
	// (GET /bookmarks)
	GetBookmarks(w http.ResponseWriter, r *http.Request)
	// Bookmark a note by UUID, optionally into a folder (BOOK-01, BOOK-03)
	// (POST /bookmarks)
	PostBookmark(w http.ResponseWriter, r *http.Request)
	// Set explicit display order for every bookmark in one folder scope (BOOK-03, drag-to-reorder)
	// (POST /bookmarks/reorder)
	ReorderBookmarks(w http.ResponseWriter, r *http.Request)
	// Remove a bookmark by id (BOOK-01)
	// (DELETE /bookmarks/{id})
	DeleteBookmark(w http.ResponseWriter, r *http.Request, id BookmarkId)
	// Move a bookmark into a folder, or to top-level when folder_id is null (BOOK-03)
	// (POST /bookmarks/{id}/folder)
	MoveBookmark(w http.ResponseWriter, r *http.Request, id BookmarkId)
	// Read user configuration
	// (GET /config)
	GetConfig(w http.ResponseWriter, r *http.Request)
	// Partially update user configuration
	// (PATCH /config)
	PatchConfig(w http.ResponseWriter, r *http.Request)
	// Replace user configuration (whole-document)
	// (PUT /config)
	PutConfig(w http.ResponseWriter, r *http.Request)
	// Get-or-create today's daily note (DAILY-01..03).
	// (GET /daily-notes/{date})
	GetDailyNote(w http.ResponseWriter, r *http.Request, date string)
	// Delete a non-markdown file under notes/ (UAT-4 R7b / Plan 07-38).
	// (DELETE /files)
	DeleteFile(w http.ResponseWriter, r *http.Request, params DeleteFileParams)
	// Stream any file under the notes vault by relative path (UAT-3 R7 / Plan 07-32a).
	// (GET /files)
	GetFile(w http.ResponseWriter, r *http.Request, params GetFileParams)
	// Upload an OS file into the notes/ tree at the specified directory (UAT-3 N2 / Plan 07-34).
	// (POST /files)
	CreateFile(w http.ResponseWriter, r *http.Request, params CreateFileParams)
	// Rename / move a non-markdown file under notes/ (UAT-4 R7b / Plan 07-38).
	// (POST /files/move)
	PostFileMove(w http.ResponseWriter, r *http.Request)
	// Delete a folder (TREE-06) — non-empty requires recursive=true
	// (DELETE /folders)
	DeleteFolder(w http.ResponseWriter, r *http.Request, params DeleteFolderParams)
	// Create a folder (TREE-04)
	// (POST /folders)
	PostFolders(w http.ResponseWriter, r *http.Request)
	// Rename or move a folder (TREE-05, TREE-07)
	// (POST /folders/move)
	PostFolderMove(w http.ResponseWriter, r *http.Request)
	// List subdirectories of an absolute path (UAT-2
	// (GET /fs/list)
	GetFsList(w http.ResponseWriter, r *http.Request, params GetFsListParams)
	// Create a directory at an absolute path (folder-picker "New folder")
	// (POST /fs/mkdir)
	PostFsMkdir(w http.ResponseWriter, r *http.Request)
	// Revoke MCP write access for a folder (D-17)
	// (DELETE /mcp/grants)
	DeleteMcpGrant(w http.ResponseWriter, r *http.Request, params DeleteMcpGrantParams)
	// List all MCP write grants (MCP-01)
	// (GET /mcp/grants)
	GetMcpGrants(w http.ResponseWriter, r *http.Request)
	// Grant (or upgrade) MCP write access for a folder (MCP-01, D-17)
	// (POST /mcp/grants)
	PostMcpGrant(w http.ResponseWriter, r *http.Request)
	// List all indexed notes (metadata only)
	// (GET /notes)
	GetNotes(w http.ResponseWriter, r *http.Request)
	// Create a new note (TREE-03)
	// (POST /notes)
	PostNotes(w http.ResponseWriter, r *http.Request)
	// Lookup a note by its relative path (D-30 deep-link fallback)
	// (GET /notes/by-path)
	GetNoteByPath(w http.ResponseWriter, r *http.Request, params GetNoteByPathParams)
	// Search note titles for wiki-link autocomplete (LINKS-06 / D-13)
	// (GET /notes/search-titles)
	GetNotesSearchTitles(w http.ResponseWriter, r *http.Request, params GetNotesSearchTitlesParams)
	// Delete a note by UUID (TREE-06)
	// (DELETE /notes/{id})
	DeleteNoteById(w http.ResponseWriter, r *http.Request, id NoteId)
	// Read a note by UUID
	// (GET /notes/{id})
	GetNoteById(w http.ResponseWriter, r *http.Request, id NoteId)
	// Replace the content of a note by UUID
	// (PUT /notes/{id})
	PutNoteById(w http.ResponseWriter, r *http.Request, id NoteId, params PutNoteByIdParams)
	// List notes that link to this note (LINKS-08 / D-27)
	// (GET /notes/{id}/backlinks)
	GetNoteBacklinks(w http.ResponseWriter, r *http.Request, id NoteId)
	// Rename or move a note (TREE-05, TREE-07)
	// (POST /notes/{id}/move)
	PostNoteMove(w http.ResponseWriter, r *http.Request, id NoteId)
	// Reveal a note path in the host OS file manager (SHARE-01)
	// (POST /reveal)
	PostReveal(w http.ResponseWriter, r *http.Request)
	// FTS5 full-text search over note bodies and tag values (SEARCH-01..04).
	// (GET /search)
	SearchNotes(w http.ResponseWriter, r *http.Request, params SearchNotesParams)
	// Submit the first-run wizard (INSTALL-07, D-10)
	// (POST /setup)
	PostSetup(w http.ResponseWriter, r *http.Request)
	// First-run wizard status (INSTALL-07, D-04)
	// (GET /setup/status)
	GetSetupStatus(w http.ResponseWriter, r *http.Request)
	// Debounced wizard-side validation of a proposed data directory (D-08)
	// (POST /setup/validate-data-dir)
	PostSetupValidateDataDir(w http.ResponseWriter, r *http.Request)
	// List all tags with note counts (TAGS-03)
	// (GET /tags)
	GetTags(w http.ResponseWriter, r *http.Request)
	// Remove a tag from all notes (TAGS-07 / D-24)
	// (DELETE /tags/{name})
	DeleteTag(w http.ResponseWriter, r *http.Request, name TagName)
	// Rename a tag across all notes (TAGS-06 / D-23)
	// (PUT /tags/{name})
	PutTag(w http.ResponseWriter, r *http.Request, name TagName)
	// List notes carrying a specific tag (TAGS-04 / D-02)
	// (GET /tags/{name}/notes)
	GetTagNotes(w http.ResponseWriter, r *http.Request, name TagName)
	// Return the full folder/file hierarchy under notes/ (TREE-01)
	// (GET /tree)
	GetTree(w http.ResponseWriter, r *http.Request)
	// Get server-assembled vault facts for the Settings About pane (Phase 32 / SET3-04, D-22)
	// (GET /vault/about)
	GetVaultAbout(w http.ResponseWriter, r *http.Request)
	// Create a new vault inside a chosen folder; runs migrations; registers in recent_vaults
	// (POST /vault/create)
	PostVaultCreate(w http.ResponseWriter, r *http.Request)
	// Get the currently open vault (or null if none)
	// (GET /vault/current)
	GetVaultCurrent(w http.ResponseWriter, r *http.Request)
	// Remove an entry from recent_vaults (idempotent; does NOT delete the vault on disk)
	// (POST /vault/forget)
	PostVaultForget(w http.ResponseWriter, r *http.Request)
	// Open an existing vault (must already contain a .jasper/ directory)
	// (POST /vault/open)
	PostVaultOpen(w http.ResponseWriter, r *http.Request)
	// Get the recent_vaults list (newest-first; missing entries included with missing=true)
	// (GET /vault/recent)
	GetVaultRecent(w http.ResponseWriter, r *http.Request)
	// Hot-swap from the currently open vault to a target vault
	// (POST /vault/switch)
	PostVaultSwitch(w http.ResponseWriter, r *http.Request)
	// Read the per-vault workspace preferences document (SORT-01, SORT-02, SORT-03, TAGS-01)
	// (GET /vault/workspace)
	GetVaultWorkspace(w http.ResponseWriter, r *http.Request)
	// Persist a sort/panel preference to the workspace document (SORT-01, SORT-02, SORT-03, TAGS-01)
	// (PUT /vault/workspace)
	PutVaultWorkspace(w http.ResponseWriter, r *http.Request)
	// WebSocket endpoint (HTTP/1.1 Upgrade)
	// (GET /ws)
	GetApiV1Ws(w http.ResponseWriter, r *http.Request, params GetApiV1WsParams)
}

